return {["scripts/items/black_mage_die.lua"]={["Path"]="scripts/items/black_mage_die.lua",["SHA256"]="efbea8dca6ba641de307cfb275698653ba2b993ebd2ccce27b9f73511c040bb1",["Text"]="-----------------------------------\n-- ID: 5480\n-- Black Mage Die\n-- Teaches the job ability Wizard's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.WIZARDS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.WIZARDS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/black_prawn.lua"]={["Path"]="scripts/items/black_prawn.lua",["SHA256"]="f38651fa57352b2cdf3479b16a00baa8d56a2d8a7b9cbd2cc8db39967637e5e2",["Text"]="-----------------------------------\n-- ID: 5948\n-- Item: Black Prawn\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- DEX -5\n-- VIT +3\n-- DEF +16% (cap 50)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -5)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FOOD_DEFP, 16)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/black_sole.lua"]={["Path"]="scripts/items/black_sole.lua",["SHA256"]="3c7a7f842c826356c40c8282983bd37262841c4ca8c2423bf15d1fcb4a77e1d4",["Text"]="-----------------------------------\n-- ID: 4384\n-- Item: Black Sole\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 4\n-- Mind -6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/blackened_frog.lua"]={["Path"]="scripts/items/blackened_frog.lua",["SHA256"]="c78e7b24440cd8cdc618c6ca00d30889c1bfd9839378ee97414918f5383c3fbb",["Text"]="-----------------------------------\n-- ID: 4536\n-- Item: Blackened Frog\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 2\n-- Agility 2\n-- Mind -2\n-- Attack % 14\n-- Attack Cap 75\n-- Ranged ATT % 14\n-- Ranged ATT Cap 75\n-- Evasion +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.FOOD_ATTP, 14)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 75)\n    effect:addMod(xi.mod.FOOD_RATTP, 14)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 75)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/blackened_muddy_siredon.lua"]={["Path"]="scripts/items/blackened_muddy_siredon.lua",["SHA256"]="caf65211389f9b922e47d852aade4734a3b637a3edfb0f9879d5ca51eacfb164",["Text"]="-----------------------------------\n-- ID: 5266\n-- Item: Blackened Muddy Siredon\n-- Item Effect: Temporarily removes Shikaree regain\n-----------------------------------\nlocal ID = zones[xi.zone.BONEYARD_GULLY]\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, player)\n    local result = xi.msg.basic.ITEM_UNABLE_TO_USE\n\n    if\n        target:getPool() == xi.mobPool.SHIKAREE_X or\n        target:getPool() == xi.mobPool.SHIKAREE_Y or\n        target:getPool() == xi.mobPool.SHIKAREE_Z\n    then\n        result = 0\n    elseif target:checkDistance(player) > 10 then\n        result = xi.msg.basic.TOO_FAR_AWAY\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, player)\n    local pool = target:getPool()\n    local siredonCount = target:getLocalVar('siredonCount')\n\n    -- Shikaree Z rejects the second siredon\n    if pool == xi.mobPool.SHIKAREE_Z and siredonCount >= 1 then\n        target:messageText(target, ID.text.SHIKAREE_Z_OFFSET + 6) -- SIREDON_REJECT\n        return\n    end\n\n    -- Determine which accept message to use based on pool and count\n    local messageOffsets =\n    {\n        [xi.mobPool.SHIKAREE_X] = { ID.text.SHIKAREE_X_OFFSET + 5, ID.text.SHIKAREE_X_OFFSET + 6 },\n        [xi.mobPool.SHIKAREE_Y] = { ID.text.SHIKAREE_Y_OFFSET + 5, ID.text.SHIKAREE_Y_OFFSET + 6 },\n        [xi.mobPool.SHIKAREE_Z] = { ID.text.SHIKAREE_Z_OFFSET + 5 },\n    }\n\n    local messages = messageOffsets[pool]\n    local messageIndex = math.min(siredonCount + 1, #messages)\n    local messageOffset = messages[messageIndex]\n\n    -- Display acceptance message\n    target:messageText(target, messageOffset)\n\n    -- Increment siredon count\n    target:setLocalVar('siredonCount', siredonCount + 1)\n\n    -- Disable regain for 60 seconds (use GetSystemTime for game timing)\n    target:setLocalVar('siredonTimer', GetSystemTime() + 60)\n    target:setMod(xi.mod.REGAIN, 0)\nend\n\nreturn itemObject\n"},["scripts/items/blackened_newt.lua"]={["Path"]="scripts/items/blackened_newt.lua",["SHA256"]="594b4df5c031b1e04feeeac11f523707d72b4d3214a8cc275dba989b01ca4cca",["Text"]="-----------------------------------\n-- ID: 4581\n-- Item: Blackened Newt\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Dexterity 4\n-- Mind -3\n-- Attack % 18\n-- Attack Cap 60\n-- Virus Resist 4\n-- Curse Resist 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.FOOD_ATTP, 18)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 60)\n    effect:addMod(xi.mod.VIRUSRES, 4)\n    effect:addMod(xi.mod.CURSERES, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/blackened_toad.lua"]={["Path"]="scripts/items/blackened_toad.lua",["SHA256"]="65029b8be2ffe0f86ca63def87fe5c498ccca434d339d1013daced0bac087284",["Text"]="-----------------------------------\n-- ID: 4599\n-- Item: Blackened Toad\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Dexterity 2\n-- Agility 2\n-- Mind -1\n-- Poison Resist 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.POISONRES, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/blacksmiths_belt.lua"]={["Path"]="scripts/items/blacksmiths_belt.lua",["SHA256"]="159d70b3ff5c213a759c8187da75593c8677d0140b09194dfcdd2c433d4ffa2f",["Text"]="-----------------------------------\n-- ID: 15445\n-- Item: Blacksmith's Belt\n-- Enchantment: Synthesis image support\n-- Duration: 8Min\n-- Smithing Skill +3\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.SMITHING_IMAGERY) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.SMITHING_IMAGERY, { power = 3, duration = 480, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/blaze_feather.lua"]={["Path"]="scripts/items/blaze_feather.lua",["SHA256"]="ff3666f5763e80683a55619dca20d7dd52b05b5a2df0e61acdfafeea50185142",["Text"]="-----------------------------------\n-- ID: 5257\n-- Item: Blaze Feather\n-- Status Effect: Blaze Spikes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.BLAZE_SPIKES, { power = 10, duration = 90, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/blaze_hose.lua"]={["Path"]="scripts/items/blaze_hose.lua",["SHA256"]="fc395bcab409953805950049cf141ee029657553250a6031b89c1883c4c07e87",["Text"]="-----------------------------------\n-- ID: 15652\n-- Item: Blaze Hose\n-- Item Effect: Blaze Spikes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:delStatusEffect(xi.effect.BLAZE_SPIKES)\n    target:addStatusEffect(xi.effect.BLAZE_SPIKES, { power = 15, duration = 180, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/blind_bolt_quiver.lua"]={["Path"]="scripts/items/blind_bolt_quiver.lua",["SHA256"]="dbc95248b4bcb9cec670c959917c549f111af08c4c8769d54586b297b481e766",["Text"]="-----------------------------------\n-- ID: 5334\n-- Item: Blind Bolt Quiver\n-- When used, you will obtain one stack of Blind Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BLIND_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/blindfish.lua"]={["Path"]="scripts/items/blindfish.lua",["SHA256"]="8028788987dab01d8206ba79d76c0e4e30715ae6fd2af57c9785d677def1b5da",["Text"]="-----------------------------------\n-- ID: 4313\n-- Item: Blindfish\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/blink_band.lua"]={["Path"]="scripts/items/blink_band.lua",["SHA256"]="f424628a976f151fa7598d1cf1448d104253ffe7fb5eb4ff75a44cdb8a797a2a",["Text"]="-----------------------------------\n-- ID: 15170\n-- Item: Blink Band\n-- Item Effect: 3 shadows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if\n        target:hasStatusEffect(xi.effect.COPY_IMAGE) or\n        target:hasStatusEffect(xi.effect.THIRD_EYE)\n    then\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    else\n        target:addStatusEffect(xi.effect.BLINK, { power = 3, duration = 300, origin = user })\n        target:messageBasic(xi.msg.basic.GAINS_EFFECT_OF_STATUS, xi.effect.BLINK)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/blissful_chapeau.lua"]={["Path"]="scripts/items/blissful_chapeau.lua",["SHA256"]="892b2cfd42b391f8a52fc2b361cd1bb62a2c571056ac15e598a168eeb03a768f",["Text"]="-----------------------------------\n-- ID: 16078\n-- Item: Blissful Chapeau\n-- Item Effect: Restores 30-40 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local mpHeal = math.randomInt(30, 40)\n    local dif = target:getMaxMP() - target:getMP()\n    if mpHeal > dif then\n        mpHeal = dif\n    end\n\n    target:addMP(mpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, mpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/blitzers_die.lua"]={["Path"]="scripts/items/blitzers_die.lua",["SHA256"]="4bdbaadc9dfa8f493e1abe60ffb1fdaa336cb41d7c0e8f254297b8d1a3ab889a",["Text"]="-----------------------------------\n-- ID: 5500\n-- Blitzer's Die\n-- Teaches the job ability Blitzers Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.BLITZERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.BLITZERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/blizzard_gloves.lua"]={["Path"]="scripts/items/blizzard_gloves.lua",["SHA256"]="e43967507b1fa858ad1ab074a0c6dec3157a3845fdbe634a7231fa97d003c3b9",["Text"]="-----------------------------------\n-- ID: 14990\n-- Blizzard Gloves\n--  Enchantment: \"Enblizzard\"\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local fakeSpell = GetSpell(xi.magic.spell.ENBLIZZARD)\n    xi.spells.enhancing.useEnhancingSpell(target, target, fakeSpell)\nend\n\nreturn itemObject\n"},["scripts/items/block_of_rock_cheese.lua"]={["Path"]="scripts/items/block_of_rock_cheese.lua",["SHA256"]="c57dd8dc162ccd7773545d302b1b27b77b3a3df77f3bc1b0b3334f375d105e48",["Text"]="-----------------------------------\n-- ID: 4593\n-- Item: Block of Rock Cheese\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health % 6\n-- Health Cap 45\n-- HP Recovered while healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 6)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 45)\n    effect:addMod(xi.mod.HPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/block_of_stone_cheese.lua"]={["Path"]="scripts/items/block_of_stone_cheese.lua",["SHA256"]="4c07f572100cec88dbbd3a4b9ce3d61f99fc9568ef6a5b764abadaa860293d93",["Text"]="-----------------------------------\n-- ID: 4460\n-- Item: Block of Stone Cheese\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health +6% (cap 40)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 6)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 40)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bloodsword.lua"]={["Path"]="scripts/items/bloodsword.lua",["SHA256"]="a5d18234ecd314c39d5193aef9de3e88847baf0a898ffec4f187e0dd2616242a",["Text"]="-----------------------------------\n-- ID: 16580\n-- Item: Bloodsword\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 40, 1, 20),\n        basePower       = 40 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bloody_blade.lua"]={["Path"]="scripts/items/bloody_blade.lua",["SHA256"]="74e122240696cbf9a2d873bb8fc103ce1b616fdb9a6316ddd036cb5ddaed307e",["Text"]="-----------------------------------\n-- ID: 16556\n-- Item: Bloody Blade\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 8, 12),\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bloody_bolt.lua"]={["Path"]="scripts/items/bloody_bolt.lua",["SHA256"]="b04c9ce0b30efadc8740a6a192d5605389c8c2c7b5f70340a15d4ff71c141cbb",["Text"]="-----------------------------------\n-- ID: 18151\n-- Item: Bloody Bolt\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n    -- Minimum observed at more than -100 dStat is 57. Negative dStat does seem to drop you to 57, but scaling is currently unknown.\n    -- 92 is the upper cap starting at 48 dStat\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 60 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n        animation       = xi.subEffect.HP_DRAIN,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bloody_bolt_quiver.lua"]={["Path"]="scripts/items/bloody_bolt_quiver.lua",["SHA256"]="0b5ad19f2dac27067430a03aaa04bdc661db6f1164be0b9a0a5a6cfe26f825e7",["Text"]="-----------------------------------\n-- ID: 5339\n-- Item: Bloody Bolt Quiver\n-- When used, you will obtain one stack of Bloody Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BLOODY_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/bloody_lance.lua"]={["Path"]="scripts/items/bloody_lance.lua",["SHA256"]="ba12c8a27483075de7a7f7441fab68a45a6bab89dd4a45aa88ce85ecb5e91a8d",["Text"]="-----------------------------------\n-- ID: 16846\n-- Item: Bloody Lance\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 7, 9), -- TODO: get more samples\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.PIERCING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bloody_rapier.lua"]={["Path"]="scripts/items/bloody_rapier.lua",["SHA256"]="115f058b8179e0834b3ecd5784e9db35cbd75c507ba01487301f54eadfcc894e",["Text"]="-----------------------------------\n-- ID: 16528\n-- Item: Bloody Rapier\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 8, 12), -- Needs better data, but looks like Bloody Blade's proc rate\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.PIERCING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bloody_sword.lua"]={["Path"]="scripts/items/bloody_sword.lua",["SHA256"]="44043fbff8e2ce815c3088bfff35a4735464b77c135cf05cfb7fb50b22ccbade",["Text"]="-----------------------------------\n-- ID: 16609\n-- Item: Bloody Sword\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 8, 12),\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/blowfish.lua"]={["Path"]="scripts/items/blowfish.lua",["SHA256"]="228eaac7c0648c975fb5bfd9f54f0a50c6267babf01cca93fc6843fca6356a10",["Text"]="-----------------------------------\n-- ID: 5812\n-- Item: Blowfish\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 1\n-- Mind -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/blue_drop.lua"]={["Path"]="scripts/items/blue_drop.lua",["SHA256"]="3df75bf76ba48ccd4b6bb73ae3396e6ee6e5212c06da869788e5024d3dfeea79",["Text"]="-----------------------------------\n--  ID: 4263\n--  Item: Blue Drop\n--  Mind 5\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.MND_BOOST, { power = 5, duration = 900, origin = user })\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/blue_mage_die.lua"]={["Path"]="scripts/items/blue_mage_die.lua",["SHA256"]="d6e2367c31628d21ce7c4cef4602159cc123ab783a44a76224269101c73e4fe5",["Text"]="-----------------------------------\n-- ID: 5492\n-- Blue Mage Die\n-- Teaches the job ability Magus's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.MAGUSS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.MAGUSS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/bluetail.lua"]={["Path"]="scripts/items/bluetail.lua",["SHA256"]="46af00c9f24cfd8626cca384ada36c89a102f528ea005551839e160c78f53d90",["Text"]="-----------------------------------\n-- ID: 4399\n-- Item: Bluetail\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/boiled_crab.lua"]={["Path"]="scripts/items/boiled_crab.lua",["SHA256"]="42fecbd793e13502c8bd230c4613ce8620f31be4686c91bc4ae5028d19b07603",["Text"]="-----------------------------------\n-- ID: 4456\n-- Item: Boiled Crab\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Vitality 2\n-- defense % 27\n-- defense % 50\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.FOOD_DEFP, 27)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/boiled_crayfish.lua"]={["Path"]="scripts/items/boiled_crayfish.lua",["SHA256"]="91c5cbb761f6ece028dcba9ad19a55a9f1e671a28e44ee8f71edb49c727ff8c3",["Text"]="-----------------------------------\n-- ID: 4535\n-- Item: Boiled Crayfish\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- defense % 30\n-- defense % 25\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_DEFP, 30)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 25)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/boiled_tuna_head.lua"]={["Path"]="scripts/items/boiled_tuna_head.lua",["SHA256"]="2f1ddd71b2f1950673a76b2943534b571ec6ca06517ae2af2574025e90bca94a",["Text"]="-----------------------------------\n-- ID: 4540\n-- Item: Boiled Tuna Head\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Magic 20\n-- Dexterity 3\n-- Intelligence 4\n-- Mind -3\n-- Magic Regen While Healing 2\n-- Evasion 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.INT, 4)\n    effect:addMod(xi.mod.MND, -3)\n    effect:addMod(xi.mod.MPHEAL, 2)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/bolt_belt.lua"]={["Path"]="scripts/items/bolt_belt.lua",["SHA256"]="b78860624dff7e2b43f48d67610d5eb980408771522eb88af875cecefa25146b",["Text"]="-----------------------------------\n-- ID: 15289\n-- Bolt Belt\n-- When used, you will obtain one stack of Bronze Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BRONZE_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/bolters_die.lua"]={["Path"]="scripts/items/bolters_die.lua",["SHA256"]="6f6b4cec17573866c5d8ea3ff39fb5340dabba095ddbd2fa7d21c61a49d03696",["Text"]="-----------------------------------\n-- ID: 5497\n-- Bolter's Die\n-- Teaches the job ability Bolters Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.BOLTERS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.BOLTERS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/bonanza_biscuit.lua"]={["Path"]="scripts/items/bonanza_biscuit.lua",["SHA256"]="240592b74e0e4228353dbc93dd8fe73d6db387dfad3a95b08bc60e3e73f57394",["Text"]="-----------------------------------\n-- ID: 6566\n-- Bonanza Biscuit\n-- Enchantment: 60Min, Costume - Gargantuan Moogle with Vest (Bonanza)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 3581, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/bone_quiver.lua"]={["Path"]="scripts/items/bone_quiver.lua",["SHA256"]="3785dcacbb3e6850545c9b1e546d8566e16bb6ef7aa08213dc167adcecc48629",["Text"]="-----------------------------------\n-- ID: 4220\n-- Item: Bone Quiver\n-- When used, you will obtain one stack of Bone Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.BONE_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/boneworkers_belt.lua"]={["Path"]="scripts/items/boneworkers_belt.lua",["SHA256"]="c266dc2b1a1442a4eb7e47026751cc877de0962a761e6fae6c01d04bcf66a293",["Text"]="-----------------------------------\n-- ID: 15449\n-- Item: Boneworker's belt\n-- Enchantment: Synthesis image support\n-- Duration: 8Min\n-- Bonecraft Skill +3\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.BONECRAFT_IMAGERY) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.BONECRAFT_IMAGERY, { power = 3, duration = 480, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/boreas_cesti.lua"]={["Path"]="scripts/items/boreas_cesti.lua",["SHA256"]="5a42d323a0248d2fb79403be0ba46a803e206741fd9e0c61c5a8325f1d5602ac",["Text"]="-----------------------------------\n-- ID: 18359\n-- Item: Boreas Cesti\n-- Additional effect: Wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance          = 100,\n        basePower       = math.random(5, 7),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_amrita.lua"]={["Path"]="scripts/items/bottle_of_amrita.lua",["SHA256"]="29aea88173df2fc40592fbb7eeb2d868db7653b7011a18f68b9db7e39fc2e2ac",["Text"]="-----------------------------------\n-- ID: 4513\n-- Item: Amrita\n-- Item Effect: Restores 500 HP and MP over 300 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect     = target:getStatusEffect(xi.effect.REGEN)\n    local refreshEffect   = target:getStatusEffect(xi.effect.REFRESH)\n    local canApplyRegen   = not regenEffect or regenEffect:getTier() == 0\n    local canApplyRefresh = not refreshEffect or refreshEffect:getTier() == 0\n\n    if canApplyRegen then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 5, duration = 300, origin = user, tick = 3 })\n    end\n\n    if canApplyRefresh then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 5, duration = 300, origin = user, tick = 3 })\n    end\n\n    if\n        not canApplyRegen and\n        not canApplyRefresh\n    then\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when both Regen and Refresh are protected by tiered spell effects.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_antacid.lua"]={["Path"]="scripts/items/bottle_of_antacid.lua",["SHA256"]="3d72ddf4c5a77c9ce1e9a0b82e75df662f9e33c548b8eef346f07e11f79e0f46",["Text"]="-----------------------------------\n-- ID: 4153\n-- Item: Antacid\n-- Item Effect: This medicine helps remove meal effects.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:delStatusEffect(xi.effect.FOOD)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_apple_juice.lua"]={["Path"]="scripts/items/bottle_of_apple_juice.lua",["SHA256"]="6ffdee8bb27dba9c35dbae234744e19a22a30d302286e1c5dba2b3d33915d03c",["Text"]="-----------------------------------\n-- ID: 4423\n-- Item: Apple Juice\n-- Item Effect: Restores 45 MP over 135 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local refreshEffect = target:getStatusEffect(xi.effect.REFRESH)\n\n    if\n        not refreshEffect or\n        refreshEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REFRESH) -- All Refresh items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REFRESH, { power = 1, duration = 135, origin = user, tick = 3 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2 or 3 Refresh.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_ascetics_gambir.lua"]={["Path"]="scripts/items/bottle_of_ascetics_gambir.lua",["SHA256"]="b5b78498377aab7527682cbfd6c3864c3929d4eaf3833c513ef7d2d5fcb44d92",["Text"]="-----------------------------------\n-- ID:          5842\n-- Item:        bottle_of_ascetics_gambir\n-- Item Effect: MATK/MACC 50\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect1   = xi.effect.MAGIC_ATK_BOOST\n    local effect2   = xi.effect.INTENSION\n    local power1    =  50 --MATT\n    local power2    =  50 --MACC\n    local duration  = 300\n\n    xi.itemUtils.addTwoItemEffects(target, effect1, effect2, power1, power2, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_ascetics_tonic.lua"]={["Path"]="scripts/items/bottle_of_ascetics_tonic.lua",["SHA256"]="641040592b0878e85aaebeb19068a2687f5ac5717521e60e432d51c119d69ee3",["Text"]="-----------------------------------\n-- ID:          5841\n-- Item:        bottle_of_ascetics_tonic\n-- Item Effect: MATK/MACC 25\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect1   = xi.effect.MAGIC_ATK_BOOST\n    local effect2   = xi.effect.INTENSION\n    local power1    =  25 --MATT\n    local power2    =  25 --MACC\n    local duration  = 300\n\n    xi.itemUtils.addTwoItemEffects(target, effect1, effect2, power1, power2, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_assassins_drink.lua"]={["Path"]="scripts/items/bottle_of_assassins_drink.lua",["SHA256"]="ff64a7ffc90d7afc57f3144637e5333343c6a6e1d9d70ed2a91e3092403d462d",["Text"]="-----------------------------------\n-- ID: 5888\n-- Item: bottle_of_assassins_drink\n-- Item Effect: Magic Accuracy +25 (Unconfirmed)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.INTENSION\n    local power     = 25 --MAcc\n    local duration  = 90\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_berserkers_drink.lua"]={["Path"]="scripts/items/bottle_of_berserkers_drink.lua",["SHA256"]="8a21f11b8a5140ca26498f1a5fdd219347f604c1c235b72ef4deb12858893583",["Text"]="-----------------------------------\n-- ID: 5849\n-- Item: bottle_of_berserkers_drink\n-- Item Effect: Double Attack +100\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.MULTI_STRIKES\n    local power     = 100 --DA\n    local duration  =  60\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_berserkers_tonic.lua"]={["Path"]="scripts/items/bottle_of_berserkers_tonic.lua",["SHA256"]="0e0a8a47baa2f97d9181c501db6296180d92821ae99d7a147c56f95811a08c71",["Text"]="-----------------------------------\n-- ID: 5851\n-- Item: bottle_of_berserkers_tonic\n-- Item Effect: Double Attack +50\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.MULTI_STRIKES\n    local power     = 50 --DA\n    local duration  = 60\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_body_boost.lua"]={["Path"]="scripts/items/bottle_of_body_boost.lua",["SHA256"]="b00bd520f7c722a7f7bcee20df17fed4290b71a0f7afc16350597adfd983a9dd",["Text"]="-----------------------------------\n-- ID: 4172\n-- Item: Reraiser\n-- Item Effect: +50% HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 900\n    target:delStatusEffect(xi.effect.MAX_HP_BOOST)\n    target:addStatusEffect(xi.effect.MAX_HP_BOOST, { power = 50, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_bravers_drink.lua"]={["Path"]="scripts/items/bottle_of_bravers_drink.lua",["SHA256"]="1d2e3bd5ba80564c9158bd24dc9a57d60da61a7e2e85e3b908a860e3a52657da",["Text"]="-----------------------------------\n-- ID: 5390\n-- Item: bottle_of_bravers_drink\n-- Item Effect: all stats +15\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local power     = 15\n    local duration  = 180\n\n    local effects =\n    {\n        xi.effect.STR_BOOST_II,\n        xi.effect.DEX_BOOST_II,\n        xi.effect.VIT_BOOST_II,\n        xi.effect.AGI_BOOST_II,\n        xi.effect.INT_BOOST_II,\n        xi.effect.MND_BOOST_II,\n        xi.effect.CHR_BOOST_II\n    }\n\n    for _, effect in ipairs(effects) do\n        target:addStatusEffect(effect, { power = power, duration = duration, origin = user })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_buffalo_bonanza_milk.lua"]={["Path"]="scripts/items/bottle_of_buffalo_bonanza_milk.lua",["SHA256"]="98a099b04d6787141f290e7e7b955e69a53c19b2729c60e8cf2049bcf06fdabe",["Text"]="-----------------------------------\n-- ID: 5742\n-- Item: Bottle of Buffalo Bonanza Milk\n-- Item Effect: Restores 120 HP over 60 seconds.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    local regenEffect = target:getStatusEffect(xi.effect.REGEN)\n\n    if\n        not regenEffect or\n        regenEffect:getTier() == 0\n    then\n        target:delStatusEffectSilent(xi.effect.REGEN) -- All Regen items overwrite freely, and their effect expires silently if overwritten.\n\n        target:addStatusEffect(xi.effect.REGEN, { power = 2, duration = 60, origin = user, tick = 1 })\n    else\n        action:messageID(target:getID(), xi.msg.basic.ITEM_NO_EFFECT) -- Displays no effect when attempting to overwrite tier 1, 2, 3, 4 or 5 Regen.\n\n        return 0\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_cantarella.lua"]={["Path"]="scripts/items/bottle_of_cantarella.lua",["SHA256"]="cc1eb175801e48f3420a30de88e3a6c0d3caad2f01cdef2e028cfdf64d93b376",["Text"]="-----------------------------------\n-- ID: 4246\n-- Item: Cantarella\n-- Item Effect: Poison 10HP / Removes 2000 HP over 10 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.POISON) then\n        target:addStatusEffect(xi.effect.POISON, { power = 10, duration = 600, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_catholicon.lua"]={["Path"]="scripts/items/bottle_of_catholicon.lua",["SHA256"]="2115624d414bab7c1317f49f01a70aa46f09101be379800d427796f0b70e7764",["Text"]="-----------------------------------\n-- ID: 4206\n-- Item: bottle_of_catholicon\n-- Item Effect: Instantly removes up to 3 negative status effects from target\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effects = xi.itemUtils.removableEffects\n    local count = 3\n\n    xi.itemUtils.removeMultipleEffects(target, effects, count)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_catholicon_+1.lua"]={["Path"]="scripts/items/bottle_of_catholicon_+1.lua",["SHA256"]="609273e1cce6ca986fb0a6c80250fcf53777c0b0f25f802b3d0fa011c8f78fed",["Text"]="-----------------------------------\n-- ID: 4208\n-- Item: bottle_of_catholicon_+1\n-- Item Effect: Instantly removes up to 6 negative status effects from target\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effects = xi.itemUtils.removableEffects\n    local count = 6\n\n    xi.itemUtils.removeMultipleEffects(target, effects, count)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_champions_drink.lua"]={["Path"]="scripts/items/bottle_of_champions_drink.lua",["SHA256"]="4db455a508d1de015cba189317651a1c97c269c160eaa9b8f39136e339dc20d3",["Text"]="-----------------------------------\n-- ID: 5392\n-- Item: bottle_of_champions_drink\n-- Item Effect: Haste (Magic) 18% - CRITHITRATE 5%\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.POTENCY\n    local power     = 1800  --haste\n    local subpower  = 5     --crit\n    local duration  = 60\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_champions_gambir.lua"]={["Path"]="scripts/items/bottle_of_champions_gambir.lua",["SHA256"]="e70dcd85735915ddc823839413c3f74500d8ffa1667bf4707d9c09f6fffeb848",["Text"]="-----------------------------------\n-- ID: 5844\n-- Item: bottle_of_champions_gambir\n-- Item Effect: Haste (Magic) 18% - CRITHITRATE 5%\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.POTENCY\n    local power     = 1800  --haste\n    local subpower  = 5     --crit\n    local duration  = 60\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_champions_tonic.lua"]={["Path"]="scripts/items/bottle_of_champions_tonic.lua",["SHA256"]="dd05e013dc405ab5e490788228e3f4cac6d2a2a4f8d2b75d3226ba3dc7826a1e",["Text"]="-----------------------------------\n-- ID: 5843\n-- Item: bottle_of_champions_tonic\n-- Item Effect: Haste (Magic) 15% - CRITHITRATE 3%\n-----------------------------------\n\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.POTENCY\n    local power     = 1500  --haste\n    local subpower  = 3     --crit\n    local duration  = 60\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_clerics_drink.lua"]={["Path"]="scripts/items/bottle_of_clerics_drink.lua",["SHA256"]="bc4f368519b4dfbe8ef15c11bd812f91a15bf8d526860e2729e9802bb8b4b789",["Text"]="-----------------------------------\n-- ID: 5395\n-- Item: bottle_of_clerics_drink\n-- Item Effect: Instantly removes all negative status effects from nearby party members\n--              Does not remove Plague or Curse\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effects = xi.itemUtils.removableEffects\n    local count = 33\n\n    target:forMembersInRange(10, function(member)\n        xi.itemUtils.removeMultipleEffects(member, effects, count)\n    end)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_cursed_beverage.lua"]={["Path"]="scripts/items/bottle_of_cursed_beverage.lua",["SHA256"]="9144b96274eae14d0a25dcefcb9ef6a708880b00d53cdfa98d7755b7e417227c",["Text"]="-----------------------------------\n-- ID: 4157\n-- Item: Cursed Beverage\n-- Item Effect: Removes 25 HP over 180 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if not target:hasStatusEffect(xi.effect.POISON) then\n        target:addStatusEffect(xi.effect.POISON, { power = 25, duration = 180, origin = user, tick = 3 })\n    else\n        target:messageBasic(xi.msg.basic.NO_EFFECT)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_dawn_mulsum.lua"]={["Path"]="scripts/items/bottle_of_dawn_mulsum.lua",["SHA256"]="f0ee9da3895b115ba893c60d01cf4e018febd16dd4d97b817d1d6f95c7710e53",["Text"]="-----------------------------------\n-- ID: 5411\n-- Item: bottle_of_dawn_mulsum\n-- Item Effect: Instantly restores 20%-35% of pet HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:hasPet() then\n        return xi.msg.basic.REQUIRES_A_PET\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local pet = target:getPet()\n    if not pet then\n        return\n    end\n\n    local percent = math.randomInt(20, 35) * xi.settings.main.ITEM_POWER\n    local totalHP = (pet:getMaxHP() / 100) * percent\n    pet:addHP(totalHP)\n    pet:messageBasic(xi.msg.basic.RECOVERS_HP, 0, totalHP)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_ether_drops.lua"]={["Path"]="scripts/items/bottle_of_ether_drops.lua",["SHA256"]="cb1350d1baa9372d6b3ff20c47c86aae561e976c7b9e7476c0d411e74f05d25b",["Text"]="-----------------------------------\n-- ID: 5357\n-- Item: Ether Drop\n-- Item Effect: Restores 15 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addMP(15 * xi.settings.main.ITEM_POWER)\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 300, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_fanatics_drink.lua"]={["Path"]="scripts/items/bottle_of_fanatics_drink.lua",["SHA256"]="53d5e859a9d37f9dfe7369550a4f1403aa55a274528a9695a1ef780325110777",["Text"]="-----------------------------------\n-- ID: 5844\n-- Item: bottle_of_fanatics_drink\n-- Item Effect: When applied, grants UDMGPHYS -10000 for 60s\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect        = xi.effect.PHYSICAL_SHIELD\n    local duration      = 60\n    local power         = 1\n    local mitigatews    = 1\n\n    xi.itemUtils.addItemShield(target, power, duration, effect, mitigatews)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_fanatics_tonic.lua"]={["Path"]="scripts/items/bottle_of_fanatics_tonic.lua",["SHA256"]="0d808a2a7669ad64886701652768ebcd7bad585e9ef569854c339fa3d0c44f90",["Text"]="-----------------------------------\n-- ID: 5845\n-- Item: bottle_of_fanatics_tonic\n-- Item Effect: When applied, grants DMGPHYS -5000 for 60s\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect        = xi.effect.PHYSICAL_SHIELD\n    local duration      = 60\n    local power         = 0\n    local mitigatews    = 0\n\n    xi.itemUtils.addItemShield(target, power, duration, effect, mitigatews)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_fighters_drink.lua"]={["Path"]="scripts/items/bottle_of_fighters_drink.lua",["SHA256"]="8556997a5d852f336524d73cce0814ddd8cee862cdb8ff84cfe9ef411bc9fade",["Text"]="-----------------------------------\n-- ID: 5386\n-- Item: bottle_of_fighters_drink\n-- Item Effect: Accuracy +100\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.ACCURACY_BOOST\n    local power     = 100 --Accuracy\n    local duration  =  90\n\n    xi.itemUtils.addItemEffect(target, effect, power, duration)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_fools_drink.lua"]={["Path"]="scripts/items/bottle_of_fools_drink.lua",["SHA256"]="afa44ab1a95c238081733b1750f3e5b36779e8bcc5b15d1a17b2651555ea97e8",["Text"]="-----------------------------------\n-- ID: 5435\n-- Item: bottle_of_fools_drink\n-- Item Effect: When applied, grants UDMGMAGIC -10000 for 60s\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect        = xi.effect.MAGIC_SHIELD\n    local duration      = 60\n    local power         = 1\n    local nospellimmune = 0\n\n    xi.itemUtils.addItemShield(target, power, duration, effect, nospellimmune)\nend\n\nreturn itemObject\n"},["scripts/items/bottle_of_fools_tonic.lua"]={["Path"]="scripts/items/bottle_of_fools_tonic.lua",["SHA256"]="acd0b7568d96cb5b16206e9f419a679f6b513998c2e4fa05066b4b20ee10ed76",["Text"]="-----------------------------------\n-- ID: 5846\n-- Item: bottle_of_fools_tonic\n-- Item Effect: When applied, grants DMGMAGIC -5000 for 60s\n--              Does not Grant Spell Immunity (nospellimmune = 1)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect        = xi.effect.MAGIC_SHIELD\n    local duration      = 60\n    local power         = 0\n    local nospellimmune = 1\n\n    xi.itemUtils.addItemShield(target, power, duration, effect, nospellimmune)\nend\n\nreturn itemObject\n"}};
